<?php
declare(strict_types=1);
namespace WexaShelf;
final class AISettings {
 public function read():array {$p=Config::storage().'/ai-settings.json';if(!is_file($p))return ['providers'=>[],'defaultProviderId'=>'','dailyTextLimit'=>20,'dailyImageLimit'=>3,'budget'=>AIBudget::settings(null)];$v=json_decode((string)file_get_contents($p),true,32,JSON_THROW_ON_ERROR);return array_replace(['budget'=>AIBudget::settings(null)],$v);}
 public static function redact(array $v):array {foreach($v['providers'] as &$p){$p['hasKey']=!empty($p['apiKey']);unset($p['apiKey']);}return $v;}
 public function save(array $input):array {
  $dir=Config::storage();if(!is_dir($dir))mkdir($dir,0700,true);$lock=fopen($dir.'/ai-settings.lock','c');chmod($dir.'/ai-settings.lock',0600);if(!$lock||!flock($lock,LOCK_EX))throw new ApiException('AI ayarları kilitlenemedi.',503);
  try{$old=$this->read();$providers=$input['providers']??null;Validation::check(is_array($providers)&&array_is_list($providers)&&count($providers)<=10,'En fazla 10 sağlayıcı eklenebilir.');$out=[];$ids=[];
   foreach($providers as $p){Validation::check(is_array($p),'Geçersiz sağlayıcı.');$id=$p['id']??'';Validation::check(is_string($id)&&preg_match('/^[a-zA-Z0-9_-]{1,64}$/D',$id)&&!isset($ids[$id]),'Geçersiz veya yinelenen sağlayıcı kimliği.');$ids[$id]=true;$r=['id'=>$id];foreach(['label'=>100,'baseUrl'=>500,'textModel'=>150,'imageModel'=>150] as $k=>$max){$s=$p[$k]??'';Validation::check(is_string($s)&&strlen($s)<=$max&&!preg_match('/[\x00-\x1f\x7f]/',$s),'Geçersiz sağlayıcı alanı.');$r[$k]=trim($s);}Validation::check($r['label']!==''&&$r['textModel']!=='','Etiket ve metin modeli gerekli.');$r['protocol']=$p['protocol']??'';Validation::check(in_array($r['protocol'],['openai','compatible'],true),'Geçersiz protokol.');$r['imageEnabled']=($p['imageEnabled']??false)===true;Validation::check(!$r['imageEnabled']||$r['imageModel']!=='','Görsel modeli gerekli.');$key=$p['apiKey']??'';Validation::check(is_string($key)&&strlen($key)<=4096&&!preg_match('/[\x00-\x20\x7f]/',$key),'Geçersiz API anahtarı.');if(($p['deleteKey']??false)===true)$key='';elseif($key==='')foreach($old['providers'] as $prev)if($prev['id']===$id&&rtrim($prev['baseUrl'],'/')===rtrim($r['baseUrl'],'/')&&$prev['protocol']===$r['protocol'])$key=$prev['apiKey'];$r['apiKey']=$key;$r=AIProvider::validateProvider($r);$r['pricing']=AIBudget::pricing($p['pricing']??null);$out[]=$r;}
   $v=['budget'=>AIBudget::settings($input['budget']??null),'providers'=>$out,'defaultProviderId'=>$input['defaultProviderId']??'','dailyTextLimit'=>$input['dailyTextLimit']??20,'dailyImageLimit'=>$input['dailyImageLimit']??3];Validation::check(is_string($v['defaultProviderId'])&&($v['defaultProviderId']===''||isset($ids[$v['defaultProviderId']])),'Varsayılan sağlayıcı bulunamadı.');foreach(['dailyTextLimit'=>200,'dailyImageLimit'=>30] as $k=>$max)Validation::check(is_int($v[$k])&&$v[$k]>=0&&$v[$k]<=$max,'Geçersiz günlük sınır.');$tmp=tempnam($dir,'.ai-settings-');try{chmod($tmp,0600);if(file_put_contents($tmp,json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES))===false||!rename($tmp,$dir.'/ai-settings.json'))throw new ApiException('AI ayarları kaydedilemedi.',500);}finally{if(is_file($tmp))unlink($tmp);}return self::redact($v);
  }finally{flock($lock,LOCK_UN);fclose($lock);}
 }
}
